1	//! Session conformance suite for Paigasus Helikon backends, including your own.
2	//!
3	//! Each function takes a factory that returns a session. The suite runs four
4	//! tests against that session:
5	//!
6	//! - `run_append_read`: events that you append come back in order, with the
7	//!   same content.
8	//! - `run_watermark_exclusive`: a read with a watermark returns only the
9	//!   events after it.
10	//! - `run_projection`: `snapshot()` equals `project(events())`.
11	//! - `run_concurrent_writers`: tasks append at the same time and every event
12	//!   survives once.
13	//!
14	//! `run_all` runs all four tests.
15	//!
16	//! # Factory contract
17	//!
18	//! Each call to the factory must return a fresh, empty session. If you return
19	//! the same session for two calls, the second test sees the events of the first
20	//! test and fails.
21	//!
22	//! # Tokio runtime
23	//!
24	//! `run_concurrent_writers` calls `tokio::spawn`. `run_all` panics if it runs
25	//! outside a Tokio runtime. We recommend the `multi_thread` flavor with
26	//! `worker_threads = 4`. The default current-thread runtime works, but it does
27	//! not run the writers in parallel.
28	//!
29	//! # Example
30	//!
31	//! ```
32	//! use std::sync::Arc;
33	//! use paigasus_helikon_core::{MemorySession, Session};
34	//! use paigasus_helikon_sessions_testkit::run_all;
35	//!
36	//! #[tokio::main(flavor = "multi_thread", worker_threads = 4)]
37	//! async fn main() {
38	//!     run_all(|| async { Arc::new(MemorySession::new()) as Arc<dyn Session> }).await;
39	//! }
40	//! ```
41	//!
42	//! # Same core version
43	//!
44	//! The session type in your factory must come from the same
45	//! `paigasus-helikon-core` version as this crate. Run
46	//! `cargo tree -i paigasus-helikon-core`. If it fails with
47	//! "specification ... is ambiguous", your crate and the testkit resolve two
48	//! core versions. Align your `paigasus-helikon-core` requirement with the
49	//! requirement of the testkit.
50	//!
51	//! # Stability
52	//!
53	//! On 0.x versions, new sub-tests arrive in patch releases. A new sub-test can
54	//! fail a backend that passed before. To control the upgrade, pin an exact
55	//! version, for example `=0.1.0`. A requirement such as `=0.1` or `0.1` still
56	//! accepts every `0.1` patch release.
57	
58	use std::future::Future;
59	use std::sync::Arc;
60	
61	use jiff::Timestamp;
62	use paigasus_helikon_core::{ContentPart, Item, SequenceId, Session, SessionEvent};
63	
64	fn user(text: &str) -> SessionEvent {
65	    SessionEvent::UserMessage {
66	        content: vec![ContentPart::Text { text: text.into() }],
67	        ts: Timestamp::from_second(1_700_000_000).unwrap(),
68	    }
69	}
70	
71	/// Extract the text of a `UserMessage` event, panicking on any other shape.
72	/// Used by the assertions below to compare exact content and order.
73	fn event_text(ev: &SessionEvent) -> &str {
74	    match ev {
75	        SessionEvent::UserMessage { content, .. } => match content.first() {
76	            Some(ContentPart::Text { text }) => text.as_str(),
77	            other => panic!("expected leading Text content, got {other:?}"),
78	        },
79	        other => panic!("expected UserMessage, got {other:?}"),
80	    }
81	}
82	
83	/// Extract the text of a projected `Item::UserMessage`, panicking otherwise.
84	fn item_text(item: &Item) -> &str {
85	    match item {
86	        Item::UserMessage { content } => match content.first() {
87	            Some(ContentPart::Text { text }) => text.as_str(),
88	            other => panic!("expected leading Text content, got {other:?}"),
89	        },
90	        other => panic!("expected Item::UserMessage, got {other:?}"),
91	    }
92	}
93	
94	/// Append several events, read them back, assert order and count are preserved.
95	pub async fn run_append_read<F, Fut>(make: F)
96	where
97	    F: Fn() -> Fut,
98	    Fut: Future<Output = Arc<dyn Session>>,
99	{
100	    let s = make().await;
101	    s.append(&[user("a"), user("b"), user("c")]).await.unwrap();
102	    let got = s.events(None).await.unwrap();
103	    assert_eq!(got.len(), 3, "all appended events read back");
104	    // Assert exact content AND order, not just count: a backend that reordered
105	    // or corrupted payloads must fail here.
106	    let texts: Vec<&str> = got.iter().map(event_text).collect();
107	    assert_eq!(
108	        texts,
109	        ["a", "b", "c"],
110	        "events read back in exact append order with exact content"
111	    );
112	}
113	
114	/// `events(Some(SequenceId(n)))` is an exclusive watermark: returns positions > n.
115	pub async fn run_watermark_exclusive<F, Fut>(make: F)
116	where
117	    F: Fn() -> Fut,
118	    Fut: Future<Output = Arc<dyn Session>>,
119	{
120	    let s = make().await;
121	    for i in 0..5 {
122	        s.append(&[user(&format!("m{i}"))]).await.unwrap();
123	    }
124	    let after = s.events(Some(SequenceId(2))).await.unwrap();
125	    // Assert it returns exactly the right two events (positions 3 and 4) in
126	    // order — not merely "two events": a backend returning the wrong rows must fail.
127	    let texts: Vec<&str> = after.iter().map(event_text).collect();
128	    assert_eq!(
129	        texts,
130	        ["m3", "m4"],
131	        "exclusive watermark returns exactly positions 3 and 4, in order"
132	    );
133	}
134	
135	/// `snapshot()` equals `project(events())`.
136	pub async fn run_projection<F, Fut>(make: F)
137	where
138	    F: Fn() -> Fut,
139	    Fut: Future<Output = Arc<dyn Session>>,
140	{
141	    let s = make().await;
142	    s.append(&[user("p1"), user("p2")]).await.unwrap();
143	    let snap = s.snapshot().await.unwrap();
144	    let events = s.events(None).await.unwrap();
145	    let expected = paigasus_helikon_core::project(&events);
146	    assert_eq!(snap.messages.len(), expected.messages.len());
147	    assert_eq!(snap.messages.len(), 2);
148	    // Assert the projected snapshot preserves exact content and order, not just
149	    // length: a snapshot with the right count but wrong messages must fail.
150	    let texts: Vec<&str> = snap.messages.iter().map(item_text).collect();
151	    assert_eq!(
152	        texts,
153	        ["p1", "p2"],
154	        "snapshot() projects messages with exact content in order"
155	    );
156	}
157	
158	/// N tasks append concurrently to the same session; every event survives once.
159	pub async fn run_concurrent_writers<F, Fut>(make: F)
160	where
161	    F: Fn() -> Fut,
162	    Fut: Future<Output = Arc<dyn Session>>,
163	{
164	    const N_TASKS: usize = 16;
165	    const M_EVENTS: usize = 10;
166	    let session = make().await;
167	    let mut handles = Vec::new();
168	    for t in 0..N_TASKS {
169	        let s = session.clone();
170	        handles.push(tokio::spawn(async move {
171	            for j in 0..M_EVENTS {
172	                s.append(&[user(&format!("t{t}-m{j}"))]).await.unwrap();
173	            }
174	        }));
175	    }
176	    for h in handles {
177	        h.await.unwrap();
178	    }
179	    let all = session.events(None).await.unwrap();
180	    assert_eq!(
181	        all.len(),
182	        N_TASKS * M_EVENTS,
183	        "no lost or duplicated events"
184	    );
185	    let mut texts: Vec<String> = all
186	        .into_iter()
187	        .filter_map(|e| match e {
188	            SessionEvent::UserMessage { content, .. } => match content.into_iter().next() {
189	                Some(ContentPart::Text { text }) => Some(text),
190	                _ => None,
191	            },
192	            _ => None,
193	        })
194	        .collect();
195	    texts.sort();
196	    let mut expected: Vec<String> = (0..N_TASKS)
197	        .flat_map(|t| (0..M_EVENTS).map(move |j| format!("t{t}-m{j}")))
198	        .collect();
199	    expected.sort();
200	    assert_eq!(texts, expected, "every sent event present exactly once");
201	}
202	
203	/// Run the full conformance suite against `make`. `make` is invoked once per
204	/// sub-test and MUST return a fresh, empty session each time.
205	pub async fn run_all<F, Fut>(make: F)
206	where
207	    F: Fn() -> Fut,
208	    Fut: Future<Output = Arc<dyn Session>>,
209	{
210	    run_append_read(&make).await;
211	    run_watermark_exclusive(&make).await;
212	    run_projection(&make).await;
213	    run_concurrent_writers(&make).await;
214	}
