1	//! Deferred tool calls: the types a run uses to stop on a tool call that needs
2	//! a later decision, and the types a host uses to resume the run.
3	
4	use std::fmt;
5	use std::sync::{Arc, Mutex};
6	
7	use serde::{Deserialize, Serialize};
8	
9	/// A tool call that a run deferred instead of running.
10	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
11	#[non_exhaustive]
12	pub struct PendingToolCall {
13	    deferral_id: String,
14	    call_id: String,
15	    tool: String,
16	    args: serde_json::Value,
17	    prompt: String,
18	    handoff_path: Vec<String>,
19	}
20	
21	impl PendingToolCall {
22	    /// Make a pending tool call.
23	    pub fn new(
24	        deferral_id: impl Into<String>,
25	        call_id: impl Into<String>,
26	        tool: impl Into<String>,
27	        args: serde_json::Value,
28	        prompt: impl Into<String>,
29	        handoff_path: Vec<String>,
30	    ) -> Self {
31	        Self {
32	            deferral_id: deferral_id.into(),
33	            call_id: call_id.into(),
34	            tool: tool.into(),
35	            args,
36	            prompt: prompt.into(),
37	            handoff_path,
38	        }
39	    }
40	
41	    /// The id the host uses to resolve this deferral.
42	    pub fn deferral_id(&self) -> &str {
43	        &self.deferral_id
44	    }
45	
46	    /// The model-assigned id of the tool call.
47	    pub fn call_id(&self) -> &str {
48	        &self.call_id
49	    }
50	
51	    /// The name of the tool.
52	    pub fn tool(&self) -> &str {
53	        &self.tool
54	    }
55	
56	    /// The arguments of the tool call.
57	    pub fn args(&self) -> &serde_json::Value {
58	        &self.args
59	    }
60	
61	    /// The prompt for the approver.
62	    pub fn prompt(&self) -> &str {
63	        &self.prompt
64	    }
65	
66	    /// The names of the agents from the root agent to the deferring agent.
67	    pub fn handoff_path(&self) -> &[String] {
68	        &self.handoff_path
69	    }
70	
71	    /// The name of the agent that deferred the call (the last name in the path).
72	    pub fn agent(&self) -> Option<&str> {
73	        self.handoff_path.last().map(String::as_str)
