340	impl ResumePlan {
341	    /// Validate a resume request against the session log and make a plan.
342	    ///
343	    /// `events` is the full session log and `snapshot` is the session
344	    /// snapshot (a custom session can override the snapshot, so the runner
345	    /// reads both). `root_agent_name` is the name of the agent that the
346	    /// runner runs. `input` carries the host resolutions and the new input
347	    /// messages.
348	    ///
349	    /// The checks run in this order: tool items in the input, duplicate
350	    /// resolutions, no open deferrals, unknown deferral ids, unresolved
351	    /// deferrals, a session changed after the deferral, a deferred call that
352	    /// is not in the history, and a handoff path that is too deep.
353	    ///
354	    /// A `root_agent_name` that is not the first name of the handoff path is
355	    /// not an error. The agent then denies every call.
356	    pub fn from_events(
357	        events: &[crate::SessionEvent],
358	        snapshot: &crate::ConversationSnapshot,
359	        root_agent_name: &str,
360	        input: &crate::AgentInput,
361	        max_agent_depth: u32,
362	    ) -> Result<ResumePlan, InvalidResume> {
363	        use crate::{Item, SessionEvent};
364	
365	        // A nested `ContentPart::ToolUse` or `ContentPart::ToolResult` is
366	        // equal to a top-level tool item, so it is rejected too.
367	        let has_tool_part = |content: &[crate::ContentPart]| {
368	            content.iter().any(|p| {
369	                matches!(
370	                    p,
371	                    crate::ContentPart::ToolUse { .. } | crate::ContentPart::ToolResult { .. }
372	                )
373	            })
374	        };
375	        if input.messages.iter().any(|i| match i {
376	            Item::ToolCall { .. } | Item::ToolResult { .. } => true,
377	            Item::UserMessage { content }
378	            | Item::AssistantMessage { content, .. }
379	            | Item::System { content } => has_tool_part(content),
380	        }) {
381	            return Err(InvalidResume::ToolItemsInInput);
382	        }
383	
384	        let resolutions = input.resolutions();
385	        for (n, (id, _)) in resolutions.iter().enumerate() {
386	            if resolutions[..n].iter().any(|(other, _)| other == id) {
387	                return Err(InvalidResume::DuplicateResolution {
388	                    deferral_id: id.clone(),
389	                });
390	            }
391	        }
392	
393	        let open = open_deferral_positions(events);
394	        let Some(&(first, _)) = open.first() else {
395	            return Err(InvalidResume::NoOpenDeferrals);
396	        };
397	
398	        for (id, _) in resolutions {
399	            if !open.iter().any(|(_, c)| c.deferral_id() == id) {
400	                return Err(InvalidResume::UnknownDeferral {
401	                    deferral_id: id.clone(),
402	                });
403	            }
404	        }
405	
406	        let missing: Vec<String> = open
407	            .iter()
408	            .filter(|(_, c)| !resolutions.iter().any(|(id, _)| id == c.deferral_id()))
409	            .map(|(_, c)| c.deferral_id().to_owned())
410	            .collect();
411	        if !missing.is_empty() {
412	            return Err(InvalidResume::UnresolvedDeferrals { missing });
413	        }
414	
415	        if events[first + 1..].iter().any(|e| {
416	            matches!(
417	                e,
418	                SessionEvent::UserMessage { .. }
419	                    | SessionEvent::AssistantMessage { .. }
420	                    | SessionEvent::ToolCalled { .. }
421	            )
422	        }) {
423	            return Err(InvalidResume::SessionModified);
424	        }
425	        let path = open[0].1.handoff_path().to_vec();
426	        if path.is_empty() || open.iter().any(|(_, c)| c.handoff_path() != path) {
427	            return Err(InvalidResume::SessionModified);
428	        }
429	        let handoffs = handoff_indices(events, &path, first)?;
430	
431	        for (_, call) in &open {
432	            let messages = &snapshot.messages;
433	            let found = messages.iter().rposition(
434	                |i| matches!(i, Item::ToolCall { call_id, .. } if call_id == call.call_id()),
435	            );
436	            let valid = found.is_some_and(|p| {
437	                let same_name =
438	                    matches!(&messages[p], Item::ToolCall { name, .. } if name == call.tool());
439	                let answered = messages[p + 1..].iter().any(
440	                    |i| matches!(i, Item::ToolResult { call_id, .. } if call_id == call.call_id()),
441	                );
442	                same_name && !answered
443	            });
444	            if !valid {
445	                return Err(InvalidResume::CallNotInHistory {
446	                    call_id: call.call_id().to_owned(),
447	                });
448	            }
449	        }
450	
451	        // `path` is nonempty here (checked above). Compare the depth, not
452	        // `len > max + 1`: the addition can overflow `usize` on a 32-bit target.
453	        if path.len() - 1 > max_agent_depth as usize {
454	            return Err(InvalidResume::PathTooDeep {
455	                len: path.len(),
456	                max_agent_depth,
457	            });
458	        }
459	
460	        let mut histories = vec![snapshot.messages.clone()];
461	        if root_agent_name == path[0] {
462	            for level in 1..path.len() {
463	                histories.push(agent_view(events, &handoffs, level, events.len()));
464	            }
465	        }
466	        let transfers = (1..path.len())
467	            .map(|level| transfer_calls_before(events, handoffs[level]))
468	            .collect();
469	
470	        let calls = open
471	            .into_iter()
472	            .map(|(_, pending)| {
473	                let resolution = resolutions
474	                    .iter()
475	                    .find(|(id, _)| id == pending.deferral_id())
476	                    .map(|(_, r)| r.clone())
477	                    .expect("every open deferral has a resolution");
478	                PlannedCall {
479	                    pending,
480	                    resolution,
481	                }
482	            })
483	            .collect();
484	
485	        Ok(ResumePlan {
486	            calls,
487	            path,
488	            histories,
489	            transfers,
490	            level: 0,
491	        })
492	    }
493	
494	    /// The open deferrals in log order, each with its resolution.
495	    pub(crate) fn calls(&self) -> &[PlannedCall] {
496	        &self.calls
497	    }
498	
499	    /// The call ids of the open deferrals, in log order.
500	    pub(crate) fn call_ids(&self) -> Vec<String> {
501	        self.calls
502	            .iter()
503	            .map(|c| c.pending.call_id().to_owned())
504	            .collect()
505	    }
506	
507	    /// The name of the agent that must receive this plan.
508	    pub(crate) fn expected_agent(&self) -> &str {
509	        &self.path[self.level]
510	    }
511	
512	    /// The name of the handoff target after the receiving agent, if any.
513	    pub(crate) fn next_agent(&self) -> Option<&str> {
514	        self.path.get(self.level + 1).map(String::as_str)
515	    }
516	
517	    /// The transfer calls of the handoff response from the receiving agent to
518	    /// [`Self::next_agent`], in log order. Empty at the end of the path.
519	    pub(crate) fn transfer_calls_to_next(&self) -> &[TransferCall] {
520	        self.transfers.get(self.level).map_or(&[], Vec::as_slice)
521	    }
522	
523	    /// The conversation that the receiving agent saw when the call was
524	    /// deferred. At the root level this is the session snapshot, also for a
525	    /// renamed root agent. Empty for a deeper level when the plan has no
526	    /// history for it (the plan of a renamed root keeps only the snapshot).
527	    pub(crate) fn history(&self) -> &[crate::Item] {
528	        self.histories.get(self.level).map_or(&[], Vec::as_slice)
529	    }
530	
531	    /// The plan for the next agent on the handoff path.
532	    pub(crate) fn descend(&self) -> ResumePlan {
533	        ResumePlan {
534	            level: self.level + 1,
535	            ..self.clone()
536	        }
537	    }
538	
539	    /// A copy of this plan where every resolution is `Denied { reason }`.
540	    pub(crate) fn with_all_denied(&self, reason: &str) -> ResumePlan {
541	        let mut plan = self.clone();
542	        for call in &mut plan.calls {
543	            call.resolution = ToolResolution::Denied {
544	                reason: reason.to_owned(),
545	            };
546	        }
547	        plan
548	    }
549	}
550	
551	/// The log index `k_i` of the `HandoffOccurred` event into `path[i]` for each
552	/// level `i` (`k_0 = 0`), all before `deferred_at`.
553	///
554	/// The search runs from the deepest level back to the root: `k_i` is the last
555	/// matching handoff before `k_{i+1}`. So a path that visits an agent two times
556	/// finds the handoffs of the latest chain.
557	fn handoff_indices(
558	    events: &[crate::SessionEvent],
559	    path: &[String],
560	    deferred_at: usize,
561	) -> Result<Vec<usize>, InvalidResume> {
562	    use crate::SessionEvent;
563	    let mut indices = vec![0; path.len()];
564	    let mut upper = deferred_at;
565	    for level in (1..path.len()).rev() {
566	        let k = events[..upper]
567	            .iter()
568	            .rposition(|e| {
569	                matches!(e, SessionEvent::HandoffOccurred { from, to, .. }
570	                    if *from == path[level - 1] && *to == path[level])
571	            })
572	            .ok_or(InvalidResume::SessionModified)?;
573	        indices[level] = k;
574	        upper = k;
575	    }
576	    Ok(indices)
577	}
578	
579	/// `view(level, end)`: the conversation of `path[level]` over `events[..end]`.
580	///
581	/// `view(0, end)` is the projection of `events[..end]`. A child view threads
582	/// the parent view at its handoff (no tool items, plus a transfer note) and
583	/// then adds the projection of the events after the handoff.
584	///
585	/// A child view pairs each tool result with one open call of the view: the
586	/// result closes the earliest open call with its call id. The view drops a
587	/// result that closes no open call. The session recorder closes the
588	/// transfer calls of a run with a synthetic result after the handoff, and
589	/// the child view has no transfer call. A child call can use the call id of
590	/// a transfer call, so a match by call id alone can keep two results for one
591	/// call.
592	fn agent_view(
593	    events: &[crate::SessionEvent],
594	    handoffs: &[usize],
595	    level: usize,
596	    end: usize,
597	) -> Vec<crate::Item> {
598	    use crate::Item;
599	    if level == 0 {
600	        return crate::project(&events[..end]).messages;
601	    }
602	    let k = handoffs[level];
603	    let mut view =
604	        crate::loop_state::thread_handoff_transcript(&agent_view(events, handoffs, level - 1, k));
605	    view.extend(crate::project(&events[k + 1..end]).messages);
606	    // The call ids of the open calls, in view order.
607	    let mut open: Vec<String> = Vec::new();
608	    view.retain(|item| match item {
609	        Item::ToolCall { call_id, .. } => {
610	            open.push(call_id.clone());
611	            true
612	        }
613	        Item::ToolResult { call_id, .. } => match open.iter().position(|c| c == call_id) {
614	            Some(p) => {
615	                open.remove(p);
616	                true
617	            }
618	            None => false,
619	        },
620	        _ => true,
621	    });
622	    view
623	}
624	
625	/// One transfer call of a handoff response, found by its position.
626	///
627	/// Two calls on the path can have the same call id, so the call id alone
628	/// does not find the call. `later_calls` is the number of `ToolCalled`
629	/// events with the same call id after this call in the log. Each
630	/// conversation on the path holds every call after a transfer call of its
631	/// own level or deeper, so the call is the `ToolCall` item with this call id
632	/// that has `later_calls` such items after it.
633	#[derive(Debug, Clone, PartialEq, Eq)]
634	pub(crate) struct TransferCall {
635	    /// The call id of the transfer call.
636	    pub(crate) call_id: String,
637	    /// The number of later `ToolCalled` events with the same call id.
638	    pub(crate) later_calls: usize,
639	}
640	
641	/// The transfer calls of the handoff at `handoff_at`, in log order.
642	///
643	/// The loop records the transfer `ToolCalled` events of a handoff response
644	/// directly before the `HandoffOccurred` event, with the assistant text of
645	/// that response. A response can hold more than one transfer call; the
646	/// first one names the target. This finds the calls by their position, not
647	/// by their tool name, because a handoff can use a custom tool name.
648	fn transfer_calls_before(events: &[crate::SessionEvent], handoff_at: usize) -> Vec<TransferCall> {
649	    use crate::SessionEvent;
650	    let start = handoff_at
651	        - events[..handoff_at]
652	            .iter()
653	            .rev()
654	            .take_while(|e| {
655	                matches!(
656	                    e,
657	                    SessionEvent::ToolCalled { .. } | SessionEvent::AssistantMessage { .. }
658	                )
659	            })
660	            .count();
661	    (start..handoff_at)
662	        .filter_map(|at| {
663	            match &events[at] {
664	            SessionEvent::ToolCalled { call_id, .. } => Some(TransferCall {
665	                call_id: call_id.clone(),
666	                later_calls: events[at + 1..]
667	                    .iter()
668	                    .filter(|e| {
669	                        matches!(e, SessionEvent::ToolCalled { call_id: id, .. } if id == call_id)
670	                    })
671	                    .count(),
672	            }),
673	            _ => None,
674	        }
675	        })
676	        .collect()
677	}
