733	/// Monotonic position in a [`Session`]'s append-only log.
734	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
735	pub struct SequenceId(pub u64);
736	
737	/// A computed projection of a [`Session`]'s log into a single
738	/// conversation state. The `messages` field is the canonical view a
739	/// session emits.
740	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
741	#[non_exhaustive]
742	pub struct ConversationSnapshot {
