746	
747	/// Errors raised by [`Session`] methods.
748	#[derive(Debug, thiserror::Error)]
749	#[non_exhaustive]
750	pub enum SessionError {
751	    /// Backend unreachable (database down, file locked, …).
752	    #[error("session backend unavailable")]
753	    Unavailable,
754	
755	    /// A backend-specific error, type-erased so core stays free of any
756	    /// particular backend dependency. The `'static` bound is required for
757	    /// `<dyn Error>::downcast_ref` to work; callers who care about
758	    /// the underlying type can do `err.downcast_ref::<sqlx::Error>()`.
759	    #[error(transparent)]
760	    Backend(Box<dyn std::error::Error + Send + Sync + 'static>),
761	
762	    /// Escape hatch.
763	    #[error(transparent)]
764	    Other(#[from] anyhow::Error),
765	}
766	
767	impl SessionError {
768	    /// Wrap a backend-specific error as [`SessionError::Backend`].
769	    ///
770	    /// Saves the
771	    /// `.map_err(|e| SessionError::Backend(Box::new(e)))` boilerplate at
772	    /// every query call site — use as `.map_err(SessionError::backend)`.
773	    pub fn backend<E>(e: E) -> Self
774	    where
775	        E: std::error::Error + Send + Sync + 'static,
776	    {
777	        Self::Backend(Box::new(e))
778	    }
779	}
