131	/// A resume request that the runner rejects as invalid.
132	#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
133	#[non_exhaustive]
134	pub enum InvalidResume {
135	    /// The session has no open deferred tool calls.
136	    #[error("the session has no open deferred tool calls")]
137	    NoOpenDeferrals,
138	    /// Some open deferred tool calls have no resolution.
139	    #[error("open deferred tool calls have no resolution: {missing:?}")]
140	    UnresolvedDeferrals {
141	        /// The deferral ids with no resolution.
142	        missing: Vec<String>,
143	    },
144	    /// A resolution names a deferral that is not open.
145	    #[error("no open deferred tool call has the id {deferral_id}")]
146	    UnknownDeferral {
147	        /// The unknown deferral id.
148	        deferral_id: String,
149	    },
150	    /// Two resolutions name the same deferral.
151	    #[error("two resolutions name the deferral {deferral_id}")]
152	    DuplicateResolution {
153	        /// The deferral id that two resolutions name.
154	        deferral_id: String,
155	    },
156	    /// The session changed after the deferral was recorded.
157	    #[error("the session changed after the deferred tool calls were recorded")]
158	    SessionModified,
159	    /// The session history has no open tool call for a deferral.
160	    ///
161	    /// A compactor removed the deferred `ToolCall` item. No resume can fix
162	    /// such a session.
163	    #[error("the session history has no open tool call {call_id} for a deferral")]
164	    CallNotInHistory {
165	        /// The call id that the history lacks.
166	        call_id: String,
167	    },
168	    /// The resume input contains tool call or tool result items, at the top
169	    /// level or nested in a message as `ContentPart::ToolUse` or
170	    /// `ContentPart::ToolResult`.
171	    #[error("the resume input contains tool call or tool result items")]
172	    ToolItemsInInput,
173	    /// The handoff path is longer than the agent depth limit allows.
174	    #[error(
175	        "the handoff path has {len} agents, more than max_agent_depth + 1 (max_agent_depth = {max_agent_depth})"
176	    )]
177	    PathTooDeep {
178	        /// The number of agents in the path.
179	        len: usize,
180	        /// The configured agent depth limit.
181	        max_agent_depth: u32,
182	    },
183	    /// The runner cannot resume deferred tool calls.
184	    #[error("this runner cannot resume deferred tool calls")]
185	    ResumeUnsupported,
186	}
