188	/// A shared slot where a run records the tool calls it deferred.
189	#[derive(Clone, Default)]
190	pub struct DeferralSlot(Arc<Mutex<Vec<PendingToolCall>>>);
191	
192	impl DeferralSlot {
193	    /// Make an empty slot.
194	    pub fn new() -> Self {
195	        Self::default()
196	    }
197	
198	    /// A copy of the recorded calls.
199	    pub fn calls(&self) -> Vec<PendingToolCall> {
200	        self.0.lock().unwrap().clone()
201	    }
202	
203	    /// Remove and return the call with this deferral id.
204	    pub(crate) fn take(&self, deferral_id: &str) -> Option<PendingToolCall> {
205	        let mut calls = self.0.lock().unwrap();
206	        let idx = calls.iter().position(|c| c.deferral_id() == deferral_id)?;
207	        Some(calls.remove(idx))
208	    }
209	
210	    /// Append calls to the slot.
211	    pub(crate) fn record(&self, calls: Vec<PendingToolCall>) {
212	        self.0.lock().unwrap().extend(calls);
213	    }
214	}
