225	/// Find the deferrals in a session log that no result has closed.
226	///
227	/// A [`SessionEvent::ToolDeferred`](crate::SessionEvent::ToolDeferred) at
228	/// position `i` is open when no
229	/// [`SessionEvent::ToolReturned`](crate::SessionEvent::ToolReturned) with the same `call_id` follows at a position
230	/// after `i`. The calls come in log order and carry the raw arguments from the
231	/// event fields.
232	///
233	/// While a deferral is open, the log holds a `ToolCall` without a
234	/// `ToolResult`. A `snapshot()` of that session is therefore not valid
235	/// provider input.
236	pub fn open_deferrals(events: &[crate::SessionEvent]) -> Vec<PendingToolCall> {
237	    open_deferral_positions(events)
238	        .into_iter()
239	        .map(|(_, call)| call)
240	        .collect()
241	}
242	
243	/// [`open_deferrals`] with the log index of each `ToolDeferred` event.
244	fn open_deferral_positions(events: &[crate::SessionEvent]) -> Vec<(usize, PendingToolCall)> {
245	    use crate::SessionEvent;
246	    let mut open = Vec::new();
247	    for (i, event) in events.iter().enumerate() {
248	        let SessionEvent::ToolDeferred {
249	            deferral_id,
250	            call_id,
251	            name,
252	            args,
253	            prompt,
254	            handoff_path,
255	            ..
256	        } = event
257	        else {
258	            continue;
259	        };
260	        let closed = events[i + 1..]
261	            .iter()
262	            .any(|e| matches!(e, SessionEvent::ToolReturned { call_id: c, .. } if c == call_id));
263	        if !closed {
264	            open.push((
265	                i,
266	                PendingToolCall::new(
267	                    deferral_id.clone(),
268	                    call_id.clone(),
269	                    name.clone(),
270	                    args.clone(),
271	                    prompt.clone(),
272	                    handoff_path.clone(),
273	                ),
274	            ));
275	        }
276	    }
277	    open
278	}
