299	/// A validated resume of a session with open deferred tool calls.
300	///
301	/// The plan holds each open deferral of the session, in log order, with the
302	/// host decision for it. It also holds the handoff path of the deferring
303	/// agent and the conversation that each agent on that path saw.
304	///
305	/// Only [`ResumePlan::from_events`] makes a plan. A deferral-aware runner
306	/// makes it and gives it to the agent with
307	/// [`AgentInput::with_resume_plan`](crate::AgentInput::with_resume_plan).
308	#[derive(Clone)]
309	pub struct ResumePlan {
310	    /// The open deferrals in log order, each with its resolution.
311	    calls: Vec<PlannedCall>,
312	    /// The shared handoff path of the open deferrals.
313	    path: Vec<String>,
314	    /// `histories[i]` is the conversation of `path[i]`; `[0]` is the snapshot.
315	    histories: Vec<Vec<crate::Item>>,
316	    /// `transfers[i]` holds the transfer calls of the handoff response from
317	    /// `path[i]` to `path[i + 1]`, in log order.
318	    transfers: Vec<Vec<TransferCall>>,
319	    /// The path entry of the agent that receives this plan.
320	    level: usize,
321	}
322	
323	impl fmt::Debug for ResumePlan {
324	    // The calls and the histories hold raw tool arguments, so the output
325	    // shows only ids, names and lengths.
326	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
327	        f.debug_struct("ResumePlan")
328	            .field("calls", &self.calls)
329	            .field("path", &self.path)
330	            .field(
331	                "history_lens",
332	                &self.histories.iter().map(Vec::len).collect::<Vec<_>>(),
333	            )
334	            .field("transfers", &self.transfers)
335	            .field("level", &self.level)
336	            .finish()
337	    }
338	}
