551	/// The log index `k_i` of the `HandoffOccurred` event into `path[i]` for each
552	/// level `i` (`k_0 = 0`), all before `deferred_at`.
553	///
554	/// The search runs from the deepest level back to the root: `k_i` is the last
555	/// matching handoff before `k_{i+1}`. So a path that visits an agent two times
556	/// finds the handoffs of the latest chain.
557	fn handoff_indices(
558	    events: &[crate::SessionEvent],
559	    path: &[String],
560	    deferred_at: usize,
561	) -> Result<Vec<usize>, InvalidResume> {
562	    use crate::SessionEvent;
563	    let mut indices = vec![0; path.len()];
564	    let mut upper = deferred_at;
565	    for level in (1..path.len()).rev() {
566	        let k = events[..upper]
567	            .iter()
568	            .rposition(|e| {
569	                matches!(e, SessionEvent::HandoffOccurred { from, to, .. }
570	                    if *from == path[level - 1] && *to == path[level])
571	            })
572	            .ok_or(InvalidResume::SessionModified)?;
573	        indices[level] = k;
574	        upper = k;
575	    }
576	    Ok(indices)
577	}
578	
579	/// `view(level, end)`: the conversation of `path[level]` over `events[..end]`.
580	///
581	/// `view(0, end)` is the projection of `events[..end]`. A child view threads
582	/// the parent view at its handoff (no tool items, plus a transfer note) and
583	/// then adds the projection of the events after the handoff.
584	///
585	/// A child view pairs each tool result with one open call of the view: the
586	/// result closes the earliest open call with its call id. The view drops a
587	/// result that closes no open call. The session recorder closes the
588	/// transfer calls of a run with a synthetic result after the handoff, and
589	/// the child view has no transfer call. A child call can use the call id of
590	/// a transfer call, so a match by call id alone can keep two results for one
591	/// call.
592	fn agent_view(
593	    events: &[crate::SessionEvent],
594	    handoffs: &[usize],
595	    level: usize,
596	    end: usize,
597	) -> Vec<crate::Item> {
598	    use crate::Item;
599	    if level == 0 {
600	        return crate::project(&events[..end]).messages;
601	    }
602	    let k = handoffs[level];
603	    let mut view =
604	        crate::loop_state::thread_handoff_transcript(&agent_view(events, handoffs, level - 1, k));
605	    view.extend(crate::project(&events[k + 1..end]).messages);
606	    // The call ids of the open calls, in view order.
607	    let mut open: Vec<String> = Vec::new();
608	    view.retain(|item| match item {
609	        Item::ToolCall { call_id, .. } => {
610	            open.push(call_id.clone());
611	            true
612	        }
613	        Item::ToolResult { call_id, .. } => match open.iter().position(|c| c == call_id) {
614	            Some(p) => {
615	                open.remove(p);
616	                true
617	            }
618	            None => false,
619	        },
620	        _ => true,
621	    });
622	    view
623	}
624	
625	/// One transfer call of a handoff response, found by its position.
626	///
627	/// Two calls on the path can have the same call id, so the call id alone
628	/// does not find the call. `later_calls` is the number of `ToolCalled`
629	/// events with the same call id after this call in the log. Each
630	/// conversation on the path holds every call after a transfer call of its
631	/// own level or deeper, so the call is the `ToolCall` item with this call id
632	/// that has `later_calls` such items after it.
633	#[derive(Debug, Clone, PartialEq, Eq)]
634	pub(crate) struct TransferCall {
635	    /// The call id of the transfer call.
636	    pub(crate) call_id: String,
637	    /// The number of later `ToolCalled` events with the same call id.
638	    pub(crate) later_calls: usize,
639	}
640	
641	/// The transfer calls of the handoff at `handoff_at`, in log order.
642	///
643	/// The loop records the transfer `ToolCalled` events of a handoff response
644	/// directly before the `HandoffOccurred` event, with the assistant text of
645	/// that response. A response can hold more than one transfer call; the
646	/// first one names the target. This finds the calls by their position, not
647	/// by their tool name, because a handoff can use a custom tool name.
648	fn transfer_calls_before(events: &[crate::SessionEvent], handoff_at: usize) -> Vec<TransferCall> {
649	    use crate::SessionEvent;
650	    let start = handoff_at
651	        - events[..handoff_at]
652	            .iter()
653	            .rev()
654	            .take_while(|e| {
655	                matches!(
656	                    e,
657	                    SessionEvent::ToolCalled { .. } | SessionEvent::AssistantMessage { .. }
658	                )
659	            })
660	            .count();
661	    (start..handoff_at)
662	        .filter_map(|at| {
663	            match &events[at] {
664	            SessionEvent::ToolCalled { call_id, .. } => Some(TransferCall {
665	                call_id: call_id.clone(),
666	                later_calls: events[at + 1..]
667	                    .iter()
668	                    .filter(|e| {
669	                        matches!(e, SessionEvent::ToolCalled { call_id: id, .. } if id == call_id)
670	                    })
671	                    .count(),
672	            }),
673	            _ => None,
674	        }
675	        })
676	        .collect()
677	}
