1095	            [transfer("t", 1), transfer("u", 0)]
1096	        );
1097	        assert_eq!(p.descend().transfer_calls_to_next(), [transfer("t", 0)]);
1098	    }
1099	
1100	    #[test]
1101	    fn transfer_calls_to_next_are_the_handoff_calls() {
1102	        let events = handoff_fixture();
1103	        let input = AgentInput::new().with_resolution("d1", ToolResolution::Approved);
1104	        let p = ResumePlan::from_events(&events, &project(&events), "triage", &input, 8).unwrap();
1105	        assert_eq!(p.transfer_calls_to_next(), [transfer("t1", 0)]);
1106	        assert!(p.descend().transfer_calls_to_next().is_empty());
1107	
1108	        let events = three_level();
1109	        let p = plan(&events, &input).unwrap();
1110	        assert_eq!(p.transfer_calls_to_next(), [transfer("t1", 0)]);
1111	        assert_eq!(p.descend().transfer_calls_to_next(), [transfer("t2", 0)]);
1112	        let leaf = p.descend().descend();
1113	        assert_eq!(leaf.expected_agent(), "leaf");
1114	        assert!(
1115	            matches!(leaf.history().last(), Some(Item::ToolCall { call_id, .. }) if call_id == "c1")
1116	        );
1117	    }
1118	
1119	    #[test]
1120	    fn resume_plan_debug_hides_args() {
1121	        let p = plan(&two_deferrals(), &approve_both()).unwrap();
1122	        let dbg = format!("{p:?}");
1123	        assert!(!dbg.contains("amount"), "{dbg}");
1124	        assert!(dbg.contains("c1"), "{dbg}");
1125	    }
1126	}
