1	//! Redis Streams-backed [`Session`] implementation for the Paigasus Helikon SDK.
2	//!
3	//! Events are stored in a Redis Stream at key `helikon:session:{id}:events`.
4	//! Each stream entry carries four fields: `seq` (monotonic integer), `kind`
5	//! (variant tag), `payload` (JSON), and `ts` (nanoseconds since Unix epoch as
6	//! a decimal string).
7	//!
8	//! Appends use an atomic Lua script (`APPEND_SCRIPT`) to compute contiguous
9	//! sequence numbers and `XADD` all events in one round-trip. Concurrent writers
10	//! on the same session key race through Redis's single-threaded command loop —
11	//! no two batches can interleave, so sequences are gapless and duplicate-free.
12	//!
13	//! ## Quick start
14	//!
15	//! ```no_run
16	//! # use paigasus_helikon_core::Session;
17	//! # use paigasus_helikon_sessions_redis::RedisSession;
18	//! # async fn run() -> Result<(), Box<dyn std::error::Error>> {
19	//! let session = RedisSession::connect("redis://127.0.0.1/", "session-abc").await?;
20	//! session.append(&[]).await?;
21	//! # Ok(())
22	//! # }
23	//! ```
24	//!
25	//! ## BYO `ConnectionManager` (TLS, pooled)
26	//!
27	//! ```no_run
28	//! # use paigasus_helikon_sessions_redis::RedisSession;
29	//! # async fn run() -> Result<(), Box<dyn std::error::Error>> {
30	//! let client = redis::Client::open("REDACTED")?;
31	//! let conn   = redis::aio::ConnectionManager::new(client).await?;
32	//! let session = RedisSession::new(conn, "session-xyz");
33	//! # Ok(())
34	//! # }
35	//! ```
36	//!
37	//! ## Operational notes
38	//!
39	//! - **No automatic trimming.** The stream grows unboundedly. Configure
40	//!   `maxmemory-policy noeviction` (or a TTL via a sidecar) so Redis does not
41	//!   silently evict stream entries.
42	//! - **Persistence.** Use `appendonly yes` (AOF) or snapshotting to survive
43	//!   restarts. An eviction or flush loses all events for that session.
44	//!
45	//! [`Session`]: paigasus_helikon_core::Session
46	
47	use async_trait::async_trait;
48	use paigasus_helikon_core::{
49	    project, ConversationSnapshot, SequenceId, Session, SessionError, SessionEvent,
50	};
51	use redis::aio::ConnectionManager;
52	use redis::AsyncCommands;
53	
54	/// Lua script for atomic, contiguous-sequence append.
55	///
56	/// Arguments come in groups of three: `kind`, `payload`, `ts`.
57	///
58	/// `KEYS[1]` is the stream key, `KEYS[2]` the per-session sequence counter.
59	/// Each batch atomically reserves `count` sequence numbers via `INCRBY` on the
60	/// counter (which starts at 0, so the first append's base is 0), then `XADD`s
61	/// each event with its reserved `seq`. Deriving `seq` from a monotonic counter
62	/// rather than `XLEN` keeps sequence numbers gap-free **and** unique even if the
63	/// stream is later trimmed (`XTRIM`/`XDEL`) — `XLEN` would reuse old `seq`s after
64	/// a trim and corrupt `events(since)`. Returns the batch's starting `seq`.
65	const APPEND_SCRIPT: &str = r#"
66	local count = #ARGV / 3
67	local base = redis.call('INCRBY', KEYS[2], count) - count
68	for i = 0, count - 1 do
69	  redis.call('XADD', KEYS[1], '*',
70	    'seq', base + i, 'kind', ARGV[i*3 + 1], 'payload', ARGV[i*3 + 2], 'ts', ARGV[i*3 + 3])
71	end
72	return base
73	"#;
74	
75	/// Error returned when a required field is absent in a Redis Stream entry.
76	#[derive(Debug, thiserror::Error)]
77	#[error("missing field '{field}' in Redis Stream entry")]
78	struct MissingField {
79	    field: &'static str,
80	}
81	
82	/// Redis Streams-backed [`Session`]. One instance represents one session
83	/// identified by `session_id`.
84	///
85	/// Instances are cheap to clone — [`ConnectionManager`] is internally
86	/// reference-counted and multiplexes commands over a single async connection.
87	///
88	/// [`Session`]: paigasus_helikon_core::Session
89	#[derive(Clone)]
90	pub struct RedisSession {
91	    conn: ConnectionManager,
92	    session_id: String,
93	    /// Redis stream key: `helikon:session:{session_id}:events`
94	    key: String,
95	    /// Per-session monotonic sequence counter: `helikon:session:{session_id}:seq`
96	    seq_key: String,
97	}
98	
99	impl std::fmt::Debug for RedisSession {
100	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
101	        f.debug_struct("RedisSession")
102	            .field("session_id", &self.session_id)
103	            .field("key", &self.key)
104	            .field("seq_key", &self.seq_key)
105	            .field("conn", &"ConnectionManager { .. }")
106	            .finish()
107	    }
108	}
109	
110	impl RedisSession {
111	    /// Create a `RedisSession` from an existing [`ConnectionManager`].
112	    ///
113	    /// The stream key is derived as `helikon:session:{session_id}:events`.
114	    /// Use this constructor when you manage your own connection (TLS, pooling,
115	    /// custom retry policy).
116	    pub fn new(conn: ConnectionManager, session_id: impl Into<String>) -> Self {
117	        let session_id = session_id.into();
118	        let key = format!("helikon:session:{}:events", session_id);
119	        let seq_key = format!("helikon:session:{}:seq", session_id);
120	        Self {
121	            conn,
122	            session_id,
123	            key,
124	            seq_key,
125	        }
126	    }
127	
128	    /// Connect to Redis at `url` and return a session for `session_id`.
129	    ///
130	    /// `url` follows the `REDACTED` or
131	    /// `rediss://…` (TLS) scheme understood by the [`redis`] crate.
132	    ///
133	    /// # Errors
134	    ///
135	    /// Returns [`SessionError::Backend`] if the URL is invalid or the initial
136	    /// connection to Redis fails.
137	    pub async fn connect(url: &str, session_id: impl Into<String>) -> Result<Self, SessionError> {
138	        let client = redis::Client::open(url).map_err(SessionError::backend)?;
139	        let conn = redis::aio::ConnectionManager::new(client)
140	            .await
141	            .map_err(SessionError::backend)?;
142	        Ok(Self::new(conn, session_id))
143	    }
144	
145	    /// The `session_id` this instance reads and writes.
146	    pub fn session_id(&self) -> &str {
147	        &self.session_id
148	    }
149	}
150	
151	#[async_trait]
152	impl Session for RedisSession {
153	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError> {
154	        if events.is_empty() {
155	            return Ok(());
156	        }
157	        // Clone is O(1): ConnectionManager is reference-counted.
158	        let mut conn = self.conn.clone();
159	        let script = redis::Script::new(APPEND_SCRIPT);
160	        let mut invocation = script.prepare_invoke();
161	        // KEYS[1] = stream, KEYS[2] = sequence counter (order matters).
162	        invocation.key(&self.key);
163	        invocation.key(&self.seq_key);
164	        for ev in events {
165	            let kind = ev.kind();
166	            let payload = serde_json::to_string(ev).map_err(SessionError::backend)?;
167	            let ts = ev.ts_nanos_saturating().to_string();
168	            invocation.arg(kind).arg(payload).arg(ts);
169	        }
170	        // Return type i64 matches the Lua `return base` (the batch's first seq).
171	        let _: i64 = invocation
172	            .invoke_async(&mut conn)
173	            .await
174	            .map_err(SessionError::backend)?;
175	        Ok(())
176	    }
177	
178	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
179	        // `since` is exclusive: return events with seq > watermark.
180	        // Default to -1 so that None returns all events (0 > -1).
181	        let watermark: i64 = match since {
182	            // seq IDs > i64::MAX are unreachable in practice; saturate so
183	            // the filter returns empty rather than wrapping.
184	            Some(s) => i64::try_from(s.0).unwrap_or(i64::MAX),
185	            None => -1,
186	        };
187	        let mut conn = self.conn.clone();
188	        let reply: redis::streams::StreamRangeReply = conn
189	            .xrange(&self.key, "-", "+")
190	            .await
191	            .map_err(SessionError::backend)?;
192	
193	        let mut result = Vec::new();
194	        for entry in reply.ids {
195	            let seq: i64 = entry
196	                .get("seq")
197	                .ok_or_else(|| SessionError::backend(MissingField { field: "seq" }))?;
198	            if seq <= watermark {
199	                continue;
200	            }
201	            let payload: String = entry
202	                .get("payload")
203	                .ok_or_else(|| SessionError::backend(MissingField { field: "payload" }))?;
204	            let event: SessionEvent =
205	                serde_json::from_str(&payload).map_err(SessionError::backend)?;
206	            result.push(event);
207	        }
208	        Ok(result)
209	    }
210	
211	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
212	        Ok(project(&self.events(None).await?))
213	    }
214	}
