750	async fn run_tools_concurrent<Ctx>(
751	    tools: &[std::sync::Arc<dyn crate::Tool<Ctx>>],
752	    calls: &[crate::ToolCallRequest],
753	    interceptors: &crate::control::Interceptors<'_, Ctx>,
754	    tool_ctx: &crate::ToolContext<Ctx>,
755	    limit: Option<std::num::NonZeroUsize>,
756	    parent: &tracing::Span,
757	) -> (Vec<ConcurrentOutcome>, Vec<crate::AgentEvent>)
758	where
759	    Ctx: Send + Sync + 'static,
760	{
761	    let denied_events: std::sync::Mutex<Vec<crate::AgentEvent>> = std::sync::Mutex::new(Vec::new());
762	    let redact_output = interceptors.ctx.redact_output();
763	    let secrets = crate::redaction::SecretSet::from_env_and_extra(interceptors.ctx.extra_secrets());
764	    let handoff_path = interceptors.ctx.handoff_path();
765	
766	    let futures = calls.iter().map(|call| {
767	        let tool = tools.iter().find(|t| t.name() == call.name).cloned();
768	        let effect = tool
769	            .as_ref()
770	            .map(|t| t.effect())
771	            .unwrap_or(crate::ToolEffect::SideEffect);
772	        let call_id = call.call_id.clone();
773	        let name = call.name.clone();
774	        let orig_args = call.args.clone();
775	        let denied_events = &denied_events;
776	        let secrets = &secrets;
777	        let span = tool_execute_span(parent, &name, false);
778	        async move {
779	            // PreToolUse hook.
780	            let pre = interceptors
781	                .fire(&crate::HookEvent::PreToolUse {
782	                    tool: name.clone(),
783	                    args: orig_args.clone(),
784	                })
785	                .await;
786	            if let Some(reason) = pre.denied {
787	                return ConcurrentOutcome::Done(crate::ToolCallOutcome {
788	                    call_id,
789	                    result: Err(format!("blocked by PreToolUse hook: {reason}")),
790	                });
791	            }
792	            let mut args = pre.replacement.unwrap_or(orig_args);
793	
794	            // Permission authorize on the effective args. This is the pipeline
795	            // of `RunContext::authorize_tool`, with the detailed result. It
796	            // gives `Defer` only when deferred tool calls are on for this run.
797	            let decision = interceptors
798	                .authorize_detailed(&name, effect, &args, crate::context::AskPoints::Ask)
799	                .await;
800	            match decision {
801	                crate::context::Authorization::Allow => {}
802	                crate::context::Authorization::Replace { args: sanitized } => {
803	                    args = sanitized;
804	                }
805	                crate::context::Authorization::Deny { reason } => {
806	                    denied_events
807	                        .lock()
808	                        .unwrap()
809	                        .push(crate::AgentEvent::PermissionDenied {
810	                            tool: name.clone(),
811	                            reason: reason.clone(),
812	                        });
813	                    return ConcurrentOutcome::Done(crate::ToolCallOutcome {
814	                        call_id,
815	                        result: Err(format!("permission denied: {reason}")),
816	                    });
817	                }
818	                crate::context::Authorization::Defer {
819	                    prompt,
820	                    args: effective,
821	                } => {
822	                    // A call to a tool that the agent does not have is not
823	                    // deferred: an approval for it would be wasted.
824	                    if tool.is_none() {
825	                        tracing::Span::current().record("otel.status_code", "ERROR");
826	                        return ConcurrentOutcome::Done(crate::ToolCallOutcome {
827	                            call_id,
828	                            result: Err(format!("unknown tool: {name}")),
829	                        });
830	                    }
831	                    // A transfer call above this agent with the same call
832	                    // id has no result while the run goes on. The session
833	                    // log cannot keep such a deferral open, so deny the call.
834	                    if interceptors.ctx.open_call_ids().contains(&call_id) {
835	                        let reason =
836	                            format!("deferral not possible: call id {call_id} repeats in this run");
837	                        denied_events
838	                            .lock()
839	                            .unwrap()
840	                            .push(crate::AgentEvent::PermissionDenied {
841	                                tool: name.clone(),
842	                                reason: reason.clone(),
843	                            });
844	                        return ConcurrentOutcome::Done(crate::ToolCallOutcome {
845	                            call_id,
846	                            result: Err(format!("permission denied: {reason}")),
847	                        });
848	                    }
849	                    return ConcurrentOutcome::Deferred(crate::PendingToolCall::new(
850	                        crate::deferral::new_deferral_id(),
851	                        call_id,
852	                        name,
853	                        effective,
854	                        prompt,
855	                        handoff_path.to_vec(),
856	                    ));
857	                }
858	            }
859	
860	            // Invoke, PostToolUse, then redaction (the final transform).
861	            let outcome = match tool {
862	                Some(t) => {
863	                    invoke_and_finalize(&t, tool_ctx, args, interceptors, redact_output, secrets)
864	                        .await
865	                }
866	                None => {
867	                    tracing::Span::current().record("otel.status_code", "ERROR");
868	                    Err(format!("unknown tool: {name}"))
869	                }
870	            };
871	
872	            ConcurrentOutcome::Done(crate::ToolCallOutcome {
873	                call_id,
874	                result: outcome,
875	            })
876	        }
877	        .instrument(span)
878	    });
879	
880	    let outcomes = run_with_limit(futures, limit).await;
881	    (outcomes, denied_events.into_inner().unwrap())
882	}
