884	// ── Agent impl for LlmAgent ──────────────────────────────────────────────────
885	
886	#[async_trait::async_trait]
887	impl<Ctx, M, T> crate::Agent<Ctx> for LlmAgent<Ctx, M, T>
888	where
889	    Ctx: Send + Sync + 'static,
890	    M: crate::Model + 'static,
891	    T: Send + Sync + 'static,
892	{
893	    fn name(&self) -> &str {
894	        &self.name
895	    }
896	
897	    fn description(&self) -> &str {
898	        &self.description
899	    }
900	
901	    async fn run(
902	        &self,
903	        ctx: crate::RunContext<Ctx>,
904	        input: AgentInput,
905	    ) -> Result<futures_core::stream::BoxStream<'static, crate::AgentEvent>, AgentError> {
906	        use futures_util::stream::StreamExt as _;
907	
908	        // This agent is the last name in the handoff path of its deferred calls.
909	        let mut ctx = ctx;
910	        ctx.push_handoff_path(self.name.clone());
911	
912	        // Snapshot everything the stream needs — it outlives `&self`.
913	        let model = std::sync::Arc::clone(&self.model);
914	        let tools = self.tools.clone();
915	        let effective_config = ctx
