144	impl<S: Session> CompactingSession<S> {
145	    fn add_estimate(&self, events: &[SessionEvent]) {
146	        // Cheap char estimate of new events (over-approx: counts handoffs as 0 text).
147	        let snap = project(events);
148	        let chars: usize = self.counter.count(&snap.messages) * 4; // counter returns ~chars/4
149	        let prev = self.cheap_estimate.load(Ordering::Relaxed);
150	        self.cheap_estimate
151	            .store(prev.saturating_add(chars), Ordering::Relaxed);
152	    }
153	
154	    async fn maybe_compact(&self) -> Result<(), SessionError> {
155	        // 1. Cheap gate (usize::MAX on first call forces an authoritative read).
156	        if self.cheap_estimate.load(Ordering::Relaxed) <= self.threshold.saturating_mul(4) {
157	            return Ok(());
158	        }
159	        // 2. Single-flight.
160	        if self
161	            .compacting
162	            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
163	            .is_err()
164	        {
165	            return Ok(());
166	        }
167	        let _guard = CompactGuard(&self.compacting);
168	
169	        // 3. Authoritative count.
170	        let evs = self.inner.events(None).await?;
171	        // An open deferral leaves a ToolCall without a ToolResult. A summary
172	        // of that log would drop the pending call. Skip without updating the
173	        // cheap estimate, so the next append re-checks.
174	        if !open_deferrals(&evs).is_empty() {
175	            tracing::debug!(
176	                target: "paigasus::core::compaction",
177	                "CompactingSession: a deferral is open; skipping compaction"
178	            );
179	            return Ok(());
180	        }
181	        let snap = project(&evs);
182	        let tokens = self.counter.count(&snap.messages);
183	        if tokens <= self.threshold {
184	            self.cheap_estimate
185	                .store(tokens.saturating_mul(4), Ordering::Relaxed);
186	            return Ok(());
187	        }
188	        // 5. Nothing useful to collapse: empty, or the single message is already
189	        // a running System summary (re-compacting it would loop forever).
190	        // A lone UserMessage/AssistantMessage SHOULD be compacted.
191	        if snap.messages.is_empty()
192	            || (snap.messages.len() == 1 && matches!(snap.messages[0], Item::System { .. }))
193	        {
194	            return Ok(());
195	        }
196	        // 6. live = events since (and incl.) the last Compacted marker.
197	        let live = live_count(&evs);
198	
199	        // 7. Summarize.
200	        let mut messages = snap.messages.clone();
201	        messages.push(Item::UserMessage {
202	            content: vec![ContentPart::Text {
203	                text: self.prompt.clone(),
204	            }],
205	        });
206	        let req = ModelRequest {
207	            messages,
208	            tools: Vec::new(),
209	            model_settings: self.settings.clone(),
210	        };
211	        let summary = match self.collect_summary(req).await {
212	            Ok(s) => s,
213	            Err(e) => {
214	                tracing::warn!(
215	                    target: "paigasus::core::compaction",
216	                    error = %e,
217	                    "CompactingSession: summarization failed; skipping compaction"
218	                );
219	                return Ok(());
220	            }
221	        };
222	        // 8. Empty-summary guard.
223	        if summary.trim().is_empty() {
224	            tracing::warn!(
225	                target: "paigasus::core::compaction",
226	                "CompactingSession: model returned empty summary; skipping compaction"
227	            );
228	            return Ok(());
229	        }
230	        // 9. Append marker; resync cheap estimate to the summary size.
231	        self.inner
232	            .append(&[SessionEvent::compacted(summary.clone(), live as u64)])
233	            .await?;
234	        let summary_item = Item::System {
235	            content: vec![ContentPart::Text { text: summary }],
236	        };
237	        self.cheap_estimate.store(
238	            self.counter.count(&[summary_item]).saturating_mul(4),
239	            Ordering::Relaxed,
240	        );
241	        Ok(())
242	    }
243	
244	    async fn collect_summary(&self, req: ModelRequest) -> Result<String, SessionError> {
245	        let mut stream = self
246	            .model
247	            .invoke(req, CancellationToken::new())
248	            .await
249	            .map_err(|e| SessionError::Other(e.into()))?;
250	        let mut summary = String::new();
251	        while let Some(ev) = stream.next().await {
252	            match ev.map_err(|e| SessionError::Other(e.into()))? {
253	                ModelEvent::TokenDelta { text } => summary.push_str(&text),
254	                ModelEvent::Finish { .. } => break,
255	                _ => {}
256	            }
257	        }
258	        Ok(summary)
259	    }
260	}
261	
262	/// Count of events since (and including) the last `Compacted`; full length if none.
263	fn live_count(evs: &[SessionEvent]) -> usize {
264	    let last_compacted = evs
265	        .iter()
266	        .rposition(|e| matches!(e, SessionEvent::Compacted { .. }));
267	    match last_compacted {
268	        Some(i) => evs.len() - i,
269	        None => evs.len(),
270	    }
271	}
272	
273	#[async_trait]
274	impl<S: Session> Session for CompactingSession<S> {
275	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError> {
276	        self.inner.append(events).await?;
277	        self.add_estimate(events);
278	        self.maybe_compact().await?;
279	        Ok(())
280	    }
281	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
282	        self.inner.events(since).await
283	    }
284	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
285	        self.inner.snapshot().await
286	    }
287	}
