//! Behaviour tests for CompactingSession (spec §4.2, AC §11).

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use async_trait::async_trait;
use futures_core::stream::BoxStream;
use paigasus_helikon_core::{
    CancellationToken, CompactingSession, ContentPart, FinishReason, Item, MemorySession, Model,
    ModelCapabilities, ModelError, ModelEvent, ModelRequest, Session, SessionEvent, TokenCounter,
};

/// Fake model: returns a fixed summary, counting invocations.
#[derive(Clone)]
struct FakeModel {
    summary: String,
    calls: Arc<AtomicUsize>,
}
impl FakeModel {
    fn new(summary: &str) -> Self {
        Self {
            summary: summary.into(),
            calls: Arc::new(AtomicUsize::new(0)),
        }
    }
}
#[async_trait]
impl Model for FakeModel {
    async fn invoke(
        &self,
        _req: ModelRequest,
        _cancel: CancellationToken,
    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        let events = vec![
            Ok(ModelEvent::TokenDelta {
                text: self.summary.clone(),
            }),
            Ok(ModelEvent::Finish {
                reason: FinishReason::Stop,
            }),
        ];
        Ok(Box::pin(futures_util::stream::iter(events)))
    }
    fn capabilities(&self) -> ModelCapabilities {
        ModelCapabilities::default()
    }
}

/// Model that always errors on invoke.
struct ErrModel;
#[async_trait]
impl Model for ErrModel {
    async fn invoke(
        &self,
        _req: ModelRequest,
        _cancel: CancellationToken,
    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
        Err(ModelError::Unavailable)
    }
    fn capabilities(&self) -> ModelCapabilities {
        ModelCapabilities::default()
    }
}

fn user(text: &str) -> SessionEvent {
    SessionEvent::user_message(vec![ContentPart::Text { text: text.into() }])
}

// 1-token-per-char counter for exact threshold math in tests.
#[derive(Debug)]
struct CharCounter;
impl paigasus_helikon_core::TokenCounter for CharCounter {
    fn count(&self, items: &[Item]) -> usize {
        items
            .iter()
            .map(|i| match i {
                Item::UserMessage { content }
                | Item::System { content }
                | Item::AssistantMessage { content, .. } => content

        raw.len(),
        2,
        "only the pre-seeded Compacted + the handoff; no new marker appended"
    );
}

#[tokio::test]
async fn does_not_compact_while_a_deferral_is_open() {
    let model = FakeModel::new("S");
    let cs = CompactingSession::builder(MemorySession::new(), Arc::new(model.clone()))
        .token_counter(Arc::new(CharCounter))
        .threshold(100)
        .build()
        .unwrap();
    // One append puts the log far over the threshold and opens a deferral:
    // a long user message, then the deferred call.
    let call = paigasus_helikon_core::PendingToolCall::new(
        "d1",
        "c1",
        "tool",
        serde_json::json!({}),
        "approve?",
        Vec::new(),
    );
    cs.append(&[
        user(&"x".repeat(500)),
        SessionEvent::tool_called("c1", "tool", serde_json::json!({})),
        SessionEvent::tool_deferred(&call),
    ])
    .await
    .unwrap();
    let raw = cs.events(None).await.unwrap();
    assert!(
        !raw.iter()
            .any(|e| matches!(e, SessionEvent::Compacted { .. })),
        "no Compacted event while a deferral is open"
    );
    assert_eq!(model.calls.load(Ordering::SeqCst), 0, "no model call");

    // Close the deferral with the result alone. The log is still over the
    // threshold, so this append compacts.
    cs.append(&[SessionEvent::tool_returned(
        "c1",
        vec![ContentPart::Text { text: "ok".into() }],
    )])
    .await
    .unwrap();
    let raw = cs.events(None).await.unwrap();
    assert!(
        raw.iter()
            .any(|e| matches!(e, SessionEvent::Compacted { .. })),
        "compaction resumes after the deferral closes"
    );
    assert_eq!(model.calls.load(Ordering::SeqCst), 1);
}
